function getDeterministicHash(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    return Math.abs(hash);
}

export function getStickerPhotoUrl(stickerId: string, category?: string, resolvedImage?: string | null): string {
    if (resolvedImage && resolvedImage.trim().length > 0) {
        return resolvedImage;
    }
    const key = stickerId ? stickerId.toUpperCase() : '';
    if (imagesMap[key]) {
        return imagesMap[key];
    }
    if (category === 'National Teams') {
        const hashIdx = getDeterministicHash(key) % genericPlayerPhotos.length;
        return genericPlayerPhotos[hashIdx];
    }
    if (category && categoryFallbacks[category]) {
        return categoryFallbacks[category];
    }
    return 'https://images.unsplash.com/photo-1508098682722-e99c43a406b2?w=500&auto=format&fit=crop&q=80';
}
